  it.each([[false, true, 1], [true, false, 0]] as const)("ready %s to %s admits exactly %s cancel", async (before, after, expected) => {
    let armed: boolean | null = null;
    let completed: Promise<void> | null = null;
    let renderedReadyAtGesture: boolean | null = null;
    const hook = renderHook(() => {
