import { currentControlSnapshot, flushAsync, installAcpFakes, json, lastSocket, profileWrapper, type Call } from "/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/src/hooks/__tests__/acpHarness.ts";
let calls: Call[];
beforeEach(() => {
  localStorage.clear(); clearAcpCache();
  calls = installAcpFakes(call => call.url.endsWith("/acp/cancel") || call.url.endsWith("/acp/prompt") ? json({}, 202) : call.url === "/api/agents" ? json([]) : undefined);
