afterEach(() => { cleanup(); vi.unstubAllGlobals(); clearAcpCache(); });
it.each(["sdk", "current-context"])("committed turn B Stop via %s", async route => {
  const id = "sdk-commit-probe";
  let current: any;
  let oldStop: (() => void) | undefined;
  let armed = false;
  let fired = false;
  let seenAtGesture: any;
  const children = (ctx: any) => {
    current = ctx;
    return createElement(Composer, { sessionId: id, currentAgent: "claude", currentProvider: null, availableModes: ctx.state.availableModes, currentModeId: ctx.state.currentModeId, legacyMode: ctx.state.mode, configOptions: ctx.state.configOptions, pendingConfigOption: ctx.state.pendingConfigOption, setConfigOption: ctx.setConfigOption, sessionUsage: ctx.state.sessionUsage, authStatus: ctx.state.authStatus, availableCommands: ctx.state.availableCommands, connected: ctx.status === "open" && nativeInputAvailable(ctx.state), canForceEndTurn: ctx.canForceEndTurn, canSubmit: ctx.status === "open" && nativeInputAvailable(ctx.state), turnActive: ctx.state.turnActive, enqueuePrompt: ctx.sendPrompt, stopTurn: ctx.stopTurn, promptCapabilities: ctx.state.promptCapabilities, pendingAttachments: ctx.pendingAttachments, setPendingAttachments: ctx.setPendingAttachments, queuedPrompts: ctx.state.queuedPrompts, editQueuedPrompt: ctx.editQueuedPrompt });
