  expect(seenAtGesture).toMatchObject({ ready: true, open: true, buttonEnabled: true });
  expect(cancels()).toHaveLength(1);
  await act(async () => { oldStop?.(); }); await flushAsync();
  expect(cancels()).toHaveLength(1);
